proposals=[]
tag_parents={t['id']:t['parent'] for t in json.loads((ROOT/'static/data/tags.json').read_text(encoding='utf-8'))['tags']}
def narrow_tags(tags):
    ancestors=set()
    for tag in tags:
        p=tag_parents[tag]
        while p:
            ancestors.add(p)
            p=tag_parents[p]
    return [t for t in tags if t not in ancestors]
for i,r in enumerate(rows,1042):
    cat,title,point,tags,typ,near,reason,motif,scene,palette,query=r
    proposals.append(dict(id=str(i),category=cat,knowledge=dict(idea=f'idea-{i}',point=point,tags=narrow_tags(tags.split()),type=typ),compared_ids=near.split(','),reason=reason,verdict='accept'))
def save(suffix,data):
    Path(str(PREFIX)+suffix).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
if __name__=='__main__':
    save('-plan.json',dict(snapshot=SNAP,catalog_reviewed=SNAP,proposals=proposals))
    results=[]
    for i,r in enumerate(rows,1042):
        out=subprocess.check_output(['python','scripts/post-knowledge.py','search','--query',r[-1],'--limit','3'],cwd=ROOT,text=True,encoding='utf-8')
        data=json.loads(out)
        results.append(dict(id=str(i),query=r[-1],results=data['results']))
        print(str(i)+' '+r[1]+': '+' | '.join(x['id']+' '+x['point'] for x in data['results']))
    save('-searches.json',results)
